<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php'; admin_require();
$id=is_string($_GET['id']??null)?$_GET['id']:'';
$q=reg_db()->prepare('SELECT * FROM attempts WHERE id=?'); $q->execute([$id]); $a=$q->fetch();
if(!$a) { http_response_code(404); admin_page('Actividad no encontrada',true); admin_notice('Esta actividad no existe.'); admin_end(); exit; }
$q=reg_db()->prepare('SELECT * FROM responses WHERE attempt_id=? ORDER BY question_index,try_number'); $q->execute([$id]); $rows=$q->fetchAll();
admin_page('Detalle de respuestas',true); ?>
<a class="text-link" href="./">← Volver al registro</a><div class="page-heading"><div><p class="eyebrow">Detalle del estudiante</p><h1><?=reg_e($a['student_name'])?></h1><p><?=(int)$a['grade']?>.° grado · Sección <?=reg_e($a['section'])?> · Código <?=reg_e(substr($a['student_id'],0,10))?></p><p><?=reg_e($a['activity_title'])?></p></div><span class="badge <?=$a['completed_at']?'done':''?>"><?=$a['completed_at']?'Completada':'En curso'?></span></div>
<div class="metrics"><article><span>Ejercicios resueltos</span><strong><?=(int)$a['current_question']?> / <?=(int)$a['total']?></strong></article><article><span>Aciertos</span><strong><?=(int)$a['correct_count']?></strong></article><article><span>Respuestas registradas</span><strong><?=count($rows)?></strong></article><article><span>Inicio · hora de Perú</span><strong class="metric-date"><?=reg_e(reg_date($a['started_at']))?></strong></article></div>
<section class="card"><h2>Pregunta por pregunta</h2><?php if(!$rows): ?><p class="empty">El estudiante abrió la ficha y todavía no ha enviado respuestas.</p><?php else: ?><div class="table-wrap" tabindex="0" role="region" aria-label="Respuestas del estudiante"><table><thead><tr><th>N.°</th><th>Pregunta</th><th>Intento</th><th>Su respuesta</th><th>Respuesta correcta</th><th>Resultado</th><th>Fecha y hora</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=(int)$r['question_index']+1?></td><td><?=reg_e($r['question'])?></td><td><?=(int)$r['try_number']?> de 2</td><td><strong><?=(int)$r['numerator']?>/<?=(int)$r['denominator']?></strong></td><td><?=reg_e($r['expected'])?></td><td><span class="badge <?=$r['correct']?'done':'retry'?>"><?=$r['correct']?'Correcta':'Incorrecta'?></span></td><td><?=reg_e(reg_date($r['answered_at']))?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php admin_end(); ?>
